-- Synthetic only. Experimental schema, not a production migration.
PRAGMA foreign_keys=ON;
CREATE TABLE account(id TEXT PRIMARY KEY, subject TEXT NOT NULL UNIQUE);
CREATE TABLE medication(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(id) ON DELETE CASCADE, label TEXT NOT NULL, stock_half_units INTEGER CHECK(stock_half_units >= 0));
CREATE TABLE schedule(id TEXT PRIMARY KEY, medication_id TEXT NOT NULL REFERENCES medication(id) ON DELETE CASCADE, version INTEGER NOT NULL CHECK(version > 0), timezone TEXT NOT NULL, paused INTEGER NOT NULL CHECK(paused IN (0,1)));
CREATE TABLE occurrence(id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL REFERENCES schedule(id), scheduled_at TEXT NOT NULL, UNIQUE(schedule_id,scheduled_at));
CREATE TABLE dose_record(id TEXT PRIMARY KEY, medication_id TEXT NOT NULL REFERENCES medication(id) ON DELETE CASCADE, occurrence_id TEXT UNIQUE REFERENCES occurrence(id), action_id TEXT NOT NULL UNIQUE, outcome TEXT NOT NULL CHECK(outcome IN ('taken','skipped')), quantity_half_units INTEGER NOT NULL CHECK(quantity_half_units >= 0), taken_at TEXT);
CREATE TABLE stock_movement(id TEXT PRIMARY KEY, medication_id TEXT NOT NULL REFERENCES medication(id) ON DELETE CASCADE, action_id TEXT NOT NULL UNIQUE, delta_half_units INTEGER NOT NULL);
CREATE TABLE reminder(id TEXT PRIMARY KEY, occurrence_id TEXT NOT NULL REFERENCES occurrence(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('pending','cancelled','sent')), due_at TEXT NOT NULL);
CREATE INDEX reminder_due ON reminder(status,due_at);
CREATE TABLE delivery_attempt(id TEXT PRIMARY KEY, reminder_id TEXT NOT NULL REFERENCES reminder(id) ON DELETE CASCADE, result TEXT NOT NULL);
CREATE TABLE device_registration(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(id) ON DELETE CASCADE, endpoint TEXT NOT NULL UNIQUE);
CREATE TABLE notification_preference(account_id TEXT PRIMARY KEY REFERENCES account(id) ON DELETE CASCADE, names_enabled INTEGER NOT NULL CHECK(names_enabled IN (0,1)));
CREATE TABLE schema_version(id INTEGER PRIMARY KEY, version INTEGER NOT NULL);
